using System;
using System.IO;
using System.Linq;
using ReFix.Shared;
using ReFix.Hub;
namespace ReFix.Tests {
 internal static class ExtensionSourcesTests {
  internal static void Run(Action<string,bool> report){
   Action<string,Action> check=(name,test)=>{try{test();report(name,true);}catch(Exception e){Console.WriteLine(e);report(name,false);}};
   check("source profile roundtrip supports many repositories",()=>{string root=Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"refix-sources-"+Guid.NewGuid().ToString("N"));try{var store=new SharedSourceStore(root);var repos=Enumerable.Range(0,30).Select(i=>new RepositorySource("https://github.com/user/repo"+i,""));store.Save(new SourceSnapshot(new[]{root},repos));if(store.Read().Repositories.Count!=30)throw new Exception("Source count changed.");}finally{if(Directory.Exists(root))Directory.Delete(root,true);}});
   check("source package URLs scoped to repository",()=>{SourcePolicy.Package("https://github.com/u/r/releases/download/v1/mod.zip","https://github.com/u/r");Reject(()=>SourcePolicy.Package("https://github.com/u/other/a.zip","https://github.com/u/r"));Reject(()=>SourcePolicy.Package("https://evil.example/u/r/a.zip","https://github.com/u/r"));Reject(()=>SourcePolicy.Https("https://user@host/u/r"));Reject(()=>SourcePolicy.Https("https://host/u/%2e%2e/a"));Reject(()=>SourcePolicy.Https("http://host/u/r"));});
   check("source default catalog routing and redirects",()=>{if(!SourcePolicy.Catalogs(new RepositorySource("https://github.com/u/r","")).First().Contains("raw.githubusercontent.com/u/r/main"))throw new Exception();if(!SourcePolicy.Catalogs(new RepositorySource("https://gitlab.com/u/r","")).First().Contains("/-/raw/main/"))throw new Exception();if(!SourcePolicy.Catalogs(new RepositorySource("https://git.example/u/r","")).First().Contains("/raw/branch/main/"))throw new Exception();SourcePolicy.Redirect("https://github.com/u/r/a.zip","https://release-assets.githubusercontent.com/a?token=x",true);Reject(()=>SourcePolicy.Redirect("https://git.example/u/r/a.zip","https://evil.example/a.zip",true));});
   check("registered remote catalogs use bounded injected fetch and validated cache",()=>{string root=Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"refix-fetch-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(root);try{string bundle=Path.Combine(root,"catalog.json");File.WriteAllText(bundle,"{\"SchemaVersion\":1,\"Modules\":[]}");var store=new SharedSourceStore(root);store.Save(new SourceSnapshot(new string[0],new[]{new RepositorySource("https://git.example/u/r","https://catalog.example/catalog.json")}));using(var manager=new ModuleManager(root,bundle)){int count=0;manager.SourceFetch=(url,max,package)=>{count++;if(max!=1024*1024||package||url!="https://catalog.example/catalog.json")throw new Exception("Wrong fetch boundary.");return System.Text.Encoding.UTF8.GetBytes("{\"SchemaVersion\":1,\"Modules\":[{\"Id\":\"custom-tool\",\"Name\":\"Custom\",\"Version\":\"1.0.0\",\"EntryPoint\":\"a.exe\",\"Sha256\":\""+new string('a',64)+"\",\"PackageUrl\":\"https://git.example/u/r/releases/v1/a.zip\"}]}");};manager.ReloadSourcesAsync().Wait();if(count!=1||!manager.Modules.Any(m=>m.Manifest.Id=="custom-tool"))throw new Exception("Remote module missing.");manager.SourceFetch=(url,max,package)=>{throw new IOException("offline");};manager.ReloadSourcesAsync().Wait();if(!manager.Modules.Any(m=>m.Manifest.Id=="custom-tool")||manager.SourceErrors.Count==0)throw new Exception("Validated cache was not retained.");store.Save(new SourceSnapshot(new string[0],new RepositorySource[0]));manager.ReloadSourcesAsync().Wait();if(manager.Modules.Any(m=>m.Manifest.Id=="custom-tool"))throw new Exception("Removed source remained discoverable.");}}finally{if(Directory.Exists(root))Directory.Delete(root,true);}});
   check("standalone local ZIP installs verified and survives source removal",()=>{string root=Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"refix-local-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(root);try{string folder=Path.Combine(root,"extensions");Directory.CreateDirectory(folder);string zip=Path.Combine(folder,"tool.zip");using(var archive=System.IO.Compression.ZipFile.Open(zip,System.IO.Compression.ZipArchiveMode.Create)){using(var writer=new StreamWriter(archive.CreateEntry("module.json").Open()))writer.Write("{\"Id\":\"local-tool\",\"Name\":\"Local\",\"Version\":\"1.0.0\",\"EntryPoint\":\"tool.exe\"}");using(var writer=new StreamWriter(archive.CreateEntry("tool.exe").Open()))writer.Write("fixture executable content, never launched");}string bundle=Path.Combine(root,"catalog.json");File.WriteAllText(bundle,"{\"SchemaVersion\":1,\"Modules\":[]}");var store=new SharedSourceStore(root);store.Save(new SourceSnapshot(new[]{folder},new RepositorySource[0]));using(var manager=new ModuleManager(root,bundle)){var view=manager.Modules.Single(m=>m.Manifest.Id=="local-tool");if(view.Manifest.Sha256!=PackageSafety.Hash(zip))throw new Exception("ZIP hash not derived.");manager.InstallLocalAsync(view).Wait();if(view.State!="OFF")throw new Exception("Local installation failed.");}store.Save(new SourceSnapshot(new string[0],new RepositorySource[0]));using(var manager=new ModuleManager(root,bundle)){if(manager.Modules.Single(m=>m.Manifest.Id=="local-tool").InstalledVersion!="1.0.0")throw new Exception("Removed-source install was lost.");}}finally{if(Directory.Exists(root))Directory.Delete(root,true);}});
   check("withdrawn external update returns to installed manifest",()=>{using(var f=new InstalledSourceFixture()){f.CatalogVersion="2.0.0";f.Manager.ReloadSourcesAsync().Wait();f.Assert("2.0.0",InstalledSourceFixture.A);f.CatalogVersion=null;f.Manager.ReloadSourcesAsync().Wait();f.Assert("1.0.0",InstalledSourceFixture.A);f.CatalogVersion="2.0.0";f.Manager.ReloadSourcesAsync().Wait();f.SetSources();f.Manager.ReloadSourcesAsync().Wait();f.Assert("1.0.0",InstalledSourceFixture.A);}});
   check("installed source origin reserves ID across manager restart",()=>{using(var f=new InstalledSourceFixture()){f.SetSources(InstalledSourceFixture.B);f.CatalogVersion="2.0.0";f.Manager.ReloadSourcesAsync().Wait();f.Restart();f.Manager.ReloadSourcesAsync().Wait();f.Assert("1.0.0",InstalledSourceFixture.A);if(!f.Manager.SourceErrors.Any(e=>e.Contains("collision")))throw new Exception("Origin collision was not reported.");}});
   check("removed source cannot install using adjacent package or stale snapshot",()=>{using(var f=new InstalledSourceFixture()){f.CatalogVersion="2.0.0";f.Manager.ReloadSourcesAsync().Wait();var view=f.Manager.Modules.Single(m=>m.Manifest.Id=="origin-tool");string packages=Path.Combine(f.Root,"packages");Directory.CreateDirectory(packages);File.WriteAllBytes(Path.Combine(packages,"origin-tool-2.0.0.zip"),f.Package);f.SetSources();bool rejected=false;try{f.Manager.InstallLocalAsync(view).GetAwaiter().GetResult();}catch(InvalidDataException){rejected=true;}if(!rejected)throw new Exception("Removed source used an adjacent package.");if(view.InstalledVersion!="1.0.0")throw new Exception("Removed-source install replaced installed version.");}});
   check("source catalog provenance derives from configured source",()=>{string text="{\"SchemaVersion\":1,\"Modules\":[{\"Id\":\"external\",\"Name\":\"External\",\"Version\":\"1.0.0\",\"EntryPoint\":\"a.exe\",\"Sha256\":\""+new string('a',64)+"\",\"SourceRepository\":\"https://evil.example/e/r\",\"PackageUrl\":\"https://github.com/u/r/releases/download/v1/a.zip\"}]}";var doc=ModuleManager.ReadSourceCatalog(text,"https://github.com/u/r",null);if(doc.Modules[0].SourceRepository!="https://github.com/u/r")throw new Exception();Reject(()=>ModuleManager.ReadSourceCatalog(text,"https://github.com/other/repo",null));});
  }
  sealed class InstalledSourceFixture:IDisposable {
   internal const string A="https://git.example/user/source-a",B="https://git.example/user/source-b";
   internal readonly string Root,Bundle;internal readonly byte[] Package;internal ModuleManager Manager;internal string CatalogVersion="1.0.0";string selected=A;readonly string hash;
   internal InstalledSourceFixture(){Root=Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"refix-origin-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(Root);Bundle=Path.Combine(Root,"catalog.json");File.WriteAllText(Bundle,"{\"SchemaVersion\":1,\"Modules\":[]}");string zip=Path.Combine(Root,"fixture.zip");using(var archive=System.IO.Compression.ZipFile.Open(zip,System.IO.Compression.ZipArchiveMode.Create))using(var writer=new StreamWriter(archive.CreateEntry("tool.exe").Open()))writer.Write("never executed");Package=File.ReadAllBytes(zip);hash=PackageSafety.Hash(zip);SetSources(A);Restart();Manager.ReloadSourcesAsync().Wait();Manager.InstallAsync(Manager.Modules.Single(m=>m.Manifest.Id=="origin-tool")).Wait();}
   internal void SetSources(params string[] repositories){if(repositories.Length>0)selected=repositories[0];new SharedSourceStore(Root).Save(new SourceSnapshot(new string[0],repositories.Select(r=>new RepositorySource(r,"https://catalog.example/catalog.json"))));}
   internal void Restart(){if(Manager!=null)Manager.Dispose();Manager=new ModuleManager(Root,Bundle);Manager.SourceFetch=(url,max,package)=>{if(package)return Package;var modules=new System.Collections.Generic.List<ModuleManifest>();if(CatalogVersion!=null)modules.Add(new ModuleManifest{Id="origin-tool",Name="Origin",Version=CatalogVersion,EntryPoint="tool.exe",Sha256=hash,PackageUrl=selected+"/releases/"+CatalogVersion+"/tool.zip"});return System.Text.Encoding.UTF8.GetBytes(new System.Web.Script.Serialization.JavaScriptSerializer().Serialize(new CatalogDocument{SchemaVersion=1,Modules=modules}));};}
   internal void Assert(string version,string origin){var m=Manager.Modules.Single(v=>v.Manifest.Id=="origin-tool").Manifest;if(m.Version!=version||m.SourceRepository!=origin)throw new Exception("Wrong available manifest: "+m.Version+" from "+m.SourceRepository);}
   public void Dispose(){if(Manager!=null)Manager.Dispose();if(Directory.Exists(Root))Directory.Delete(Root,true);}
  }
  static void Reject(Action action){try{action();}catch(InvalidDataException){return;}throw new Exception("Unsafe source accepted.");}
 }
}
